/* game_L14.js — Moonlight Mart, Lesson 14 (making adjectives from ACTION verbs: verb stem + -는 + noun; ㄹ-stems drop ㄹ: 여는, 부는,
   아는; adjective clauses: 제가 좋아하는 노래, 민지가 좋아하는 사람 vs 민지를 좋아하는 사람).
   Lines: [castId, korean, english]. q.opts: correct option first (engine shuffles).
   odd: opts[0] is the WRONG sentence the player must find.
   Forms come from forms_L14.js (generated, checked against the book): one generated question per verb (neun).
   Game words not in the book: 닫다, 나오다, 최고, 고치다, 식당, 근처, 만두, 바람, 손, 보이다, 하루 종일, 선풍기, 부럽다 (ㅂ, Lesson 11),
   직원, 제일, 옛날 — glossed where they appear. lenient (one-jamo typo) is switched off at the end: 먹는 / 먹은, 가는 / 간. */

/* Why a wrong -는 form is wrong. Used here and by workbook_L14.js (which loads after this file). */
MM.l14why = (d, w) => {
  const f = MM.forms[14].find(x => x.dict === d), a = f.neun, stem = d.slice(0, -1), last = w.slice(-1);
  const jong = ch => { const c = ch.charCodeAt(0) - 0xAC00; return c >= 0 && c < 11172 ? c % 28 : -1; };
  if (w === f.hae) return `${w} ends a sentence. Before a noun: ${a}.`;
  if (/해는$/.test(w)) return `Start from the stem (${stem}), not from the 해요 form: ${a}.`;
  if (f.irr === 'ㄹ' && w === stem + '는') return `ㄹ-stem: drop the ㄹ, then add 는 → ${a}.`;
  if (f.irr === '르' && /는$/.test(w)) return `Just stem + 는: ${a}.`;
  if (/는$/.test(w)) return `It sounds like ${w}, but it is written ${a}.`;
  if (last === '을' || jong(last) === 8) return `That is the future form (-(으)ㄹ). Now / usually: ${a}.`;
  if (last === '은' && (f.irr === 'ㄹ' || f.irr === 'ex' || !jong(stem.slice(-1)))) return `Action verbs (and 있다) take 는: ${a}.`;
  return `-(으)ㄴ on an action verb is the past (Lesson 9: 간 것 같아요). Now / usually: ${a}.`;
};

